-- A57: batch b002_de, chunk 1 (25 videos for learners of de). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'de' and media_id in (620,5310,41,5499,119,166,596,484,68,5149,457,36,676,7962,7858,7124,6849,4206,234,5273,7835,8032,278,93,7239)) then
    raise exception 'A57 out/b002_de_01.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'de' and media_id in (620,5310,41,5499,119,166,596,484,68,5149,457,36,676,7962,7858,7124,6849,4206,234,5273,7835,8032,278,93,7239)) <> 25 then
    raise exception 'A57 out/b002_de_01.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
